const unavailable = 'Maaf, data laporan aktif belum bisa diambil saat ini. Coba lagi beberapa saat lagi.';

function countSummary(counts) {
  if (!counts || typeof counts !== 'object') return [];
  return Object.entries(counts).map(([code, value]) => {
    if (value && typeof value === 'object') {
      const count = value.count ?? value.total ?? value.value ?? 0;
      return String(count) ? code + ': ' + count : code;
    }
    return code + ': ' + value;
  });
}

let reply = unavailable;
if (!data.error && data.ok !== false) {
  const activeWarning = data.active_warning || data.activeWarning || null;
  const counts = data.counts || {};
  const summaries = countSummary(counts).filter((part) => !part.endsWith(': 0'));

  if (activeWarning) {
    const codes = Array.isArray(activeWarning.codes) ? activeWarning.codes : (activeWarning.code ? [activeWarning.code] : []);
    const codeText = codes.length ? codes.join(', ') : 'tidak tersedia';
