    reply = 'Ada laporan yang sedang dipantau di ' + beachLabel + ': ' + summaries.join('; ') + '. Tetap waspada dan pantau informasi terbaru.';
  } else {
    reply = 'Saat ini belum ada laporan aktif di ' + beachLabel + '.';
  }
}

return [{ json: { reply, chatId: ctx.chatId, session: ctx.session, messageId: ctx.messageId } }];

